func (inv *Inventory) order(text string) (*Order, error) {
	number := integer(text)
	if number < 1 || number > int64(len(inv.Orders)) {
		return nil, fmt.Errorf("unknown order %s", text)
	}
	return inv.Orders[number-1], nil
